import { boot } from 'quasar/wrappers';
import { logger } from 'src/utils/logger';
import { safeBoot } from 'src/utils/bootSafety';

declare global {
  function logError(message: string, context?: any): void;
  function logInfo(message: string, context?: any): void;
  function logDebug(message: string, context?: any): void;
  function logWarn(message: string, context?: any): void;
}

// HMR guard to prevent multiple initializations during hot reload
let isInitialized = false;

/**
 * Logger Boot File
 *
 * Sets up global logging functions for use throughout the application.
 * Console output only — telemetry is handled by Faro (src/boot/faro.ts).
 */
export default boot(safeBoot('logger', () => {
  if (isInitialized && import.meta.hot) {
    return;
  }

  globalThis.logError = (message: string, context?: any) => {
    logger.error(message, context);
  };

  globalThis.logInfo = (message: string, context?: any) => {
    logger.debug(message, context);
  };

  globalThis.logDebug = (message: string, context?: any) => {
    logger.debug(message, context);
  };

  globalThis.logWarn = (message: string, context?: any) => {
    logger.warn(message, context);
  };

  isInitialized = true;
}));

// HMR cleanup
if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    isInitialized = false;
  });
}
